const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { chromium } = require("playwright");

(async () => {
  const preview = process.env.EXAMCELL_NOTIFICATION_PREVIEW;
  if (!preview)
    throw new Error(
      "Set EXAMCELL_NOTIFICATION_PREVIEW to the HTML generated by NotificationsTest.",
    );
  const html = fs.readFileSync(preview, "utf8");
  const publicRoot = path.resolve(__dirname, "../../public");
  const browser = await chromium.launch({ headless: true, channel: "chrome" });
  try {
    const page = await browser.newPage({
      viewport: { width: 1440, height: 1000 },
    });
    let unread = 12;
    let failNext = false;
    const errors = [];
    page.on("pageerror", (error) => errors.push(error.message));
    await page.route("**/*", async (route) => {
      const request = route.request();
      const url = new URL(request.url());
      if (
        request.method() === "POST" &&
        url.pathname.startsWith("/workflow/notifications/")
      ) {
        await new Promise((resolve) => setTimeout(resolve, 150));
        if (failNext) {
          failNext = false;
          return route.fulfill({
            status: 500,
            json: { message: "Temporary failure" },
          });
        }
        unread = url.pathname.endsWith("read-all") ? 0 : unread - 1;
        return route.fulfill({
          json: { message: "Saved", unread_count: unread },
        });
      }
      if (url.pathname === "/student/profile")
        return route.fulfill({ contentType: "text/html", body: html });
      if (url.pathname === "/ui-palette.css")
        return route.fulfill({ contentType: "text/css", body: "" });
      const file = path.resolve(
        publicRoot,
        "." + decodeURIComponent(url.pathname),
      );
      if (
        file.startsWith(publicRoot + path.sep) &&
        fs.existsSync(file) &&
        fs.statSync(file).isFile()
      ) {
        const types = {
          ".js": "application/javascript",
          ".css": "text/css",
          ".svg": "image/svg+xml",
          ".ttf": "font/ttf",
          ".png": "image/png",
        };
        return route.fulfill({
          path: file,
          contentType: types[path.extname(file)] || "application/octet-stream",
        });
      }
      return route.fulfill({ status: 404, body: "Not found" });
    });
    await page.goto("http://127.0.0.1:8000/student/profile");
    await page.locator("[data-open-notifications]").click();
    const dialog = page.locator("#notification-dialog");
    await dialog.waitFor({ state: "visible" });
    assert.equal(
      await dialog.evaluate(
        (element) => getComputedStyle(element, "::backdrop").backdropFilter,
      ),
      "none",
    );
    assert.ok((await dialog.boundingBox()).height <= 681);
    const expand = dialog.locator("[data-notice-expand]").first();
    await expand.click();
    await expand
      .getAttribute("aria-expanded")
      .then((value) => assert.equal(value, "true"));
    await expand.click();
    await page.screenshot({
      path: "/private/tmp/examcell-notifications-desktop.png",
    });
    await dialog.locator("[data-notice-read] button").first().click();
    await page.waitForFunction(
      () =>
        document.querySelector("[data-unread-count]").textContent ===
        "11 unread",
    );
    assert.equal(page.url(), "http://127.0.0.1:8000/student/profile");
    assert.equal(await dialog.isVisible(), true);
    failNext = true;
    await dialog.locator("[data-notice-read] button").first().click();
    await page.waitForFunction(() =>
      document
        .querySelector("[data-notice-feedback]")
        .textContent.includes("try again"),
    );
    assert.equal(
      await dialog.locator("[data-notice-read] button").first().isEnabled(),
      true,
    );
    await dialog.locator("[data-notice-read-all] button").click();
    await page.waitForFunction(
      () =>
        document.querySelector("[data-unread-count]").textContent ===
        "0 unread",
    );
    assert.equal(await dialog.locator("[data-notice-read]").count(), 0);
    assert.equal(await page.locator("[data-unread-dot]").isVisible(), false);
    await page.setViewportSize({ width: 390, height: 844 });
    await page.screenshot({
      path: "/private/tmp/examcell-notifications-mobile.png",
    });
    assert.ok((await dialog.boundingBox()).width <= 390);
    await dialog.evaluate((element) => {
      element.scrollTop = element.scrollHeight;
    });
    const close = await dialog.locator("[data-close-dialog]").boundingBox();
    assert.ok(
      close.y >= 0 && close.y + close.height <= 844,
      "Close must stay visible while scrolling",
    );
    assert.deepEqual(errors, []);
    console.log(
      "PASS notifications: real built UI, compact layout, expand, read without reload, failure retry, bulk read, mobile, sticky close, no browser errors",
    );
  } finally {
    await browser.close();
  }
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
